import{_ as t,o as n,c as h,b6 as c,gE as a,gF as l,gG as o,gH as e,gI as s,gJ as g,gK as r,gL as u,gM as p,gN as k,gO as b,gP as d,gQ as m,gR as y,gS as v,gT as q,gU as G,gV as H,gW as S,gX as f,gY as x}from"./chunks/framework.BUXTSoD9.js";const w=JSON.parse('{"title":"Học sử dụng Git và Github","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-2/backend/git-workflow/index.md","filePath":"vi-vn/stage-2/backend/git-workflow/index.md"}'),F={name:"vi-vn/stage-2/backend/git-workflow/index.md"};function _(C,i,T,P,B,E){return n(),h("div",null,[...i[0]||(i[0]=[c('<h1 id="hoc-su-dung-git-va-github" tabindex="-1">Học sử dụng Git và Github <a class="header-anchor" href="#hoc-su-dung-git-va-github" aria-label="Permalink to “Học sử dụng Git và Github”">​</a></h1><p>Trong các bài học trước, chúng ta đã học cách viết code bằng các công cụ vibe coding dựa trên Web. Mỗi cuộc trò chuyện sẽ tạo ra một phiên bản code mới. Nhưng hãy nghĩ về một vấn đề: nếu chúng ta muốn quay lại sửa đổi trước đó, có cách nào tiện lợi không? Có công cụ nào có thể ghi lại code của chúng ta ở các giai đoạn khác nhau, cho phép chúng ta chuyển đổi và sửa đổi giữa các phiên bản bất kỳ lúc nào không?</p><p>Để đáp ứng nhu cầu này, phần mềm kiểm soát phiên bản đã ra đời. Trong bài viết này, chúng ta sẽ giới thiệu chương trình kiểm soát phiên bản nổi tiếng nhất — Git — và nền tảng lưu trữ code tốt nhất — GitHub. Chúng ta sẽ học cách sử dụng Git để quản lý code, cách lấy code của người khác từ GitHub, cách tải lên code của chính mình, và cách hợp tác với người khác trong các dự án lớn.</p><p>Cho dù là theo dõi phiên bản dự án cá nhân, đồng bộ code trong hợp tác đội nhóm, hay đóng góp cho cộng đồng mã nguồn mở, Git và GitHub đều là công cụ không thể thiếu của developer hiện đại. Bằng cách làm chủ chúng, bạn sẽ có thể quản lý code hiệu quả hơn, tạo checkpoint theo cần, chuyển đổi tự do giữa các giai đoạn code khác nhau, và dễ dàng xử lý mọi thứ từ thay đổi file đơn lẻ đến phát triển dự án lớn — làm cho mỗi lần lặp code đều có thể kiểm soát và truy xuất nguồn gốc.</p><blockquote><p>💡 <strong>Kiến thức tiên quyết</strong></p><p>Trước khi học Git, bạn nên tìm hiểu các khái niệm sau:</p><ul><li><a href="/easy-vibe-ja-learning-map/vi-vn/appendix/2-development-tools/command-line-shell.html">Terminal/Dòng lệnh là gì</a> - Học cách sử dụng dòng lệnh để tương tác với máy tính</li><li><a href="/easy-vibe-ja-learning-map/vi-vn/appendix/2-development-tools/git-version-control.html">Git là gì</a> - Hiểu các khái niệm cốt lõi của hệ thống kiểm soát phiên bản Git</li></ul><p>Bài viết này sẽ tập trung vào quy trình làm việc GitHub và thao tác thực tế, vui lòng tham khảo các liên kết phụ lục cho kiến thức cơ bản nói trên.</p></blockquote><h1 id="bat-đau-nhanh-voi-git" tabindex="-1">Bắt đầu nhanh với Git <a class="header-anchor" href="#bat-đau-nhanh-voi-git" aria-label="Permalink to “Bắt đầu nhanh với Git”">​</a></h1><p>Trước khi bắt đầu sử dụng Git, hãy đảm bảo bạn đã đọc nội dung về <a href="/easy-vibe-ja-learning-map/vi-vn/appendix/2-development-tools/command-line-shell.html">dòng lệnh</a> và <a href="/easy-vibe-ja-learning-map/vi-vn/appendix/2-development-tools/git-version-control.html">cơ bản về Git</a> trong phần phụ lục. Bài viết này sẽ giả định bạn đã có kiến thức cơ bản này và trực tiếp hướng dẫn cách cài đặt, cấu hình Git và sử dụng GitHub để cộng tác.</p><h2 id="cach-cai-đat-git" tabindex="-1">Cách cài đặt Git <a class="header-anchor" href="#cach-cai-đat-git" aria-label="Permalink to “Cách cài đặt Git”">​</a></h2><p>Chúng ta sẽ giới thiệu ba phương pháp cài đặt Git trên các hệ điều hành máy tính khác nhau. Vui lòng làm theo hướng dẫn phù hợp với phiên bản hệ thống của bạn:</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><ol><li><p>Truy cập <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Trang tải Git chính thức</a> và tải về trình cài đặt phù hợp với hệ thống của bạn: <a href="https://github.com/git-for-windows/git/releases/download/v2.51.0.windows.1/Git-2.51.0-64-bit.exe" target="_blank" rel="noreferrer">Gói cài đặt</a>. Theo mặc định, khuyến nghị sử dụng trình cài đặt x64.</p></li><li><p>Nhấp đúp vào trình cài đặt và làm theo hướng dẫn của thuật sĩ cài đặt: <img src="'+a+'" alt=""></p><ol><li>Khuyến nghị giữ các tùy chọn mặc định. Nếu bạn cần tùy chỉnh, lưu ý các điểm sau: (Trong hầu hết trường hợp, bạn có thể nhấp &quot;Next&quot; liên tục) <ul><li>Chọn trình soạn thảo mặc định Git sử dụng: Chọn trình soạn thảo bạn thích (như VS Code). Bạn có thể chọn tùy chọn đầu tiên theo mặc định, tức là Vim (một trình soạn thảo văn bản), hoặc chọn tùy chọn &quot;Visual Studio Code as Git&#39;s default editor&quot; (cần cài đặt VS Code trước). Bạn có thể giữ lựa chọn mặc định và nhấp &quot;Next&quot; để tiếp tục. <img src="'+l+'" alt=""></li><li>Chọn cách sử dụng Git: Ba tùy chọn này kiểm soát khả năng truy cập của Git trong hệ thống. Khuyến nghị chọn tùy chọn 2 (&quot;from command line and 3rd-party software&quot;) — nó thêm các công cụ Git cơ bản vào PATH, cho phép bạn sử dụng Git trong Git Bash, Command Prompt, PowerShell và IDE mà không làm rối hệ thống. <img src="'+o+'" alt=""></li></ul></li></ol></li><li><p>Sau khi cài đặt, nhấp chuột phải trên màn hình. Nếu bạn thấy &quot;Git Bash Here&quot; trong menu, cài đặt đã thành công.</p></li></ol><p><img src="'+e+`" alt=""></p><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to “MacOS”">​</a></h3><p>Đối với macOS, bạn có thể nhập <code>git --version</code> trong terminal để kiểm tra xem Git đã được cài đặt chưa. Nếu chưa, hệ thống sẽ nhắc bạn cài đặt — chỉ cần làm theo hướng dẫn để hoàn tất cài đặt.</p><ol><li>Phương pháp 1: Cài đặt qua Homebrew Nếu bạn đã cài đặt <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a> (trình quản lý gói Mac), hãy mở terminal và nhập<div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div></li><li>Phương pháp 2: (Khuyến nghị) Cài đặt qua Xcode: <a href="https://developer.apple.com/xcode/" target="_blank" rel="noreferrer">https://developer.apple.com/xcode/</a>, Xcode đã tích hợp sẵn Git. Sau khi cài đặt, chỉ cần làm theo hướng dẫn để tiếp tục.</li></ol><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>Hầu hết các bản phân phối Linux có thể cài đặt Git thông qua trình quản lý gói:</p><ul><li>Ubuntu/Debian:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>CentOS/RHEL:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>Xác minh cài đặt: Nhập git --version trong terminal. Nếu hiển thị số phiên bản, cài đặt đã thành công.</li></ul><h2 id="khoi-tao-git" tabindex="-1">Khởi tạo Git <a class="header-anchor" href="#khoi-tao-git" aria-label="Permalink to “Khởi tạo Git”">​</a></h2><p>Sau khi cài đặt Git, đầu tiên bạn cần cấu hình thông tin người dùng — đây là bước cơ bản khi sử dụng Git để kiểm soát phiên bản. Thực hiện các lệnh sau trong terminal (thay thế nội dung trong ngoặc bằng thông tin của bạn):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Đặt tên người dùng toàn cục (sẽ hiển thị trong bản ghi commit)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Đặt email toàn cục (khuyến nghị sử dụng email đã đăng ký trên GitHub/GitLab)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>Git sẽ nhúng thông tin này vào mỗi bản ghi commit, làm &quot;thông tin tác giả&quot; cho mỗi lần sửa đổi. Khi xem lịch sử phiên bản (ví dụ: sử dụng git log), bạn có thể thấy rõ ai đã sửa đổi mỗi dòng code, thuận tiện cho việc truy trách nhiệm và giao tiếp. Trong dự án cộng tác, thông tin danh tính thống nhất giúp thành viên nhóm nhanh chóng nhận diện ai đã thực hiện thay đổi nào, từ đó nâng cao hiệu quả cộng tác (ví dụ: tìm developer liên quan thông qua bản ghi commit để thảo luận vấn đề).</p><p>Bạn có thể nhập <code>git config --list</code> trong dòng lệnh để xem thông tin cấu hình Git hiện tại và xác nhận cài đặt thành công.</p><h1 id="github-la-gi" tabindex="-1">GitHub là gì <a class="header-anchor" href="#github-la-gi" aria-label="Permalink to “GitHub là gì”">​</a></h1><p>GitHub là một nền tảng lưu trữ code dựa trên Git. Nó không chỉ cung cấp lưu trữ từ xa cho các kho lưu trữ Git mà còn bao gồm các công cụ cộng tác (như Issues, Pull Requests, Projects), giúp developer dễ dàng chia sẻ code và hợp tác hơn. Nói một cách đơn giản, Git là công cụ kiểm soát phiên bản cục bộ, còn GitHub là &quot;đĩa cloud kho code + cộng đồng cộng tác&quot; từ xa.</p><p>GitHub không chỉ là nền tảng lưu trữ code lớn nhất thế giới mà còn là cộng đồng mã nguồn mở năng động và có sức ảnh hưởng nhất toàn cầu. Ý tưởng cốt lõi của &quot;mã nguồn mở&quot; ở đây là bất kỳ ai cũng có thể tải xuống và chạy mã nguồn của phần mềm. Mô hình này cho phép mọi người trên thế giới kiểm tra code của nhau và thực hiện sửa đổi, hoặc tạo dự án mới dựa trên đó. Ví dụ: bạn có thể tìm thấy nhiều hướng dẫn học tập cũng như mã nguồn hoàn chỉnh của framework huấn luyện mô hình GPT (như PyTorch) trên GitHub. Mỗi ngày, vô số người trên toàn thế giới cộng tác kiểm tra và cải thiện code.</p><p><img src="`+s+'" alt=""></p><p>Nhiều công ty lớn mở mã nguồn chương trình hoặc hướng dẫn của họ trên GitHub để đạt lợi thế cạnh tranh trong ngành — điều này cũng có thể xem là một hình thức quảng cáo. Trong cộng đồng GitHub, số &quot;ngôi sao (stars)&quot; mà dự án nhận được là thước đo chính về giá trị của dự án; dự án hoặc tổ chức càng có nhiều sao thì uy tín và sức ảnh hưởng càng lớn.</p><p><img src="'+g+'" alt=""></p><p>Trong khóa học của chúng ta, tài nguyên hỗ trợ và bài tập cũng sẽ được tải lên kho lưu trữ GitHub chuyên dụng. Thông qua quá trình tải lên bài tập, bạn sẽ dần làm quen và nắm vững việc sử dụng GitHub, tạo nền tảng vững chắc cho việc kiểm soát phiên bản trong phát triển ứng dụng tương lai.</p><h2 id="đang-ky-tai-khoan-github" tabindex="-1">Đăng ký tài khoản GitHub <a class="header-anchor" href="#đang-ky-tai-khoan-github" aria-label="Permalink to “Đăng ký tài khoản GitHub”">​</a></h2><ol><li>Truy cập <a href="https://github.com/" target="_blank" rel="noreferrer">Trang chủ GitHub</a> và nhấp &quot;Sign up&quot; ở góc trên bên phải. <img src="'+r+'" alt=""></li><li>Nhập địa chỉ email của bạn (khuyến nghị sử dụng email thường xuyên sử dụng, vì xác minh và thông báo sẽ được gửi đến đó), đặt mật khẩu (phải bao gồm chữ cái, số và ký tự đặc biệt).</li><li>Hoàn thành xác minh con người, xác minh email theo hướng dẫn, tài khoản của bạn đã được tạo.</li></ol><h2 id="tao-kho-luu-tru-đau-tien-tren-github" tabindex="-1">Tạo kho lưu trữ đầu tiên trên GitHub <a class="header-anchor" href="#tao-kho-luu-tru-đau-tien-tren-github" aria-label="Permalink to “Tạo kho lưu trữ đầu tiên trên GitHub”">​</a></h2><p>Tiếp theo, chúng ta sẽ tạo thư mục lưu trữ đầu tiên, còn được gọi là kho lưu trữ hoặc &quot;repo&quot;.</p><p><img src="'+u+'" alt=""><img src="'+p+'" alt=""></p><p><img src="'+k+'" alt=""></p><ol><li>Repository name: Tên kho lưu trữ hiển thị cho người khác.</li><li>Description: Mô tả chi tiết về kho lưu trữ.</li><li>Choose visibility: Đối với kho cá nhân, nếu đặt là private, chỉ bạn và những người được mời đặc biệt mới có thể xem. Nếu đặt là public, tất cả mọi người đều có thể xem. Đối với kho trong tổ chức, nếu là Private, chỉ người trong tổ chức mới có thể xem. Nếu là Public, người ngoài tổ chức cũng có thể xem.</li><li>README: Thông thường, mỗi kho đều nên có file README. Bạn có thể coi nó như bản giới thiệu đầy đủ về kho, bao gồm hướng dẫn sử dụng, danh sách file và cách thao tác.</li><li>Add .gitignore and license: <ol><li>File .gitignore báo cho Git biết bỏ qua một số thư mục hoặc file nhất định khi tải lên GitHub, do đó chúng sẽ không được theo dõi hoặc thêm vào staging area. Điều này rất hữu ích cho các file kiểm thử tạm thời, gói dependency hoặc file lớn. Khi đã chỉ định, các file này sẽ không còn được theo dõi.</li><li>license là loại giấy phép mã nguồn mở bạn chọn. Các giấy phép khác nhau quy định chi tiết việc người khác có thể sử dụng code của bạn cho mục đích thương mại hay không, cùng với các điều khoản và điều kiện khác.</li></ol></li></ol><p>Khuyến nghị tích &quot;Add README&quot;, đặt khả năng hiển thị kho là &quot;Private&quot;, điền tên kho và mô tả theo sở thích của bạn, sau đó nhấp &quot;Create repository&quot; để hoàn tất việc tạo kho lưu trữ từ xa đầu tiên.</p><p><img src="'+b+'" alt=""></p><p>Sau đó, bạn sẽ có một kho sạch không có file bổ sung nào. Tiếp theo bạn có thể bắt đầu tải file lên.</p><p><img src="'+d+'" alt=""></p><p>Lệnh để lấy kho là <code>git clone</code>, nhưng nó cần địa chỉ kho. Bạn có thể tìm địa chỉ kho bằng cách nhấp nút &quot;Code&quot; màu xanh lá, bạn sẽ thấy các tùy chọn HTTPS và SSH. Thông thường, bạn có thể sử dụng bất kỳ phương pháp nào trong hai phương pháp này để tải kho về máy cục bộ (chỉ có như vậy bạn mới có thể sửa đổi và tải file lên).</p><p><img src="'+m+'" alt=""></p><p>Nói chung, kho được clone qua HTTP phù hợp để tải xuống và kiểm thử tạm thời kho của người khác, nhưng không khuyến nghị cho phát triển cá nhân. Để có trải nghiệm học tập tốt hơn, bạn nên thiết lập xác thực SSH trước.</p><h2 id="lien-ket-ssh-cuc-bo" tabindex="-1">Liên kết SSH cục bộ <a class="header-anchor" href="#lien-ket-ssh-cuc-bo" aria-label="Permalink to “Liên kết SSH cục bộ”">​</a></h2><p>Trong GitHub, &quot;liên kết giao thức SSH&quot; về bản chất là việc liên kết SSH public key của thiết bị cục bộ với tài khoản GitHub của bạn, cho phép GitHub nhận diện thiết bị của bạn thông qua giao thức SSH. Điều này cho phép bạn vận hành kho lưu trữ từ xa một cách an toàn mà không cần mật khẩu (như clone, push hoặc pull code).</p><p>Nói đơn giản: Điều này giống như cấp cho thiết bị của bạn một &quot;thẻ kiểm soát truy cập GitHub chuyên dụng&quot;. Sau khi liên kết, khi thiết bị của bạn truy cập kho GitHub thông qua giao thức SSH, GitHub sẽ xác minh &quot;thẻ kiểm soát truy cập&quot; (SSH public key của bạn). Khi đã xác nhận là thiết bị được ủy quyền, bạn có thể trực tiếp vận hành — không cần nhập tài khoản và mật khẩu mỗi lần.</p><blockquote><p>💡 SSH là gì</p></blockquote><h3 id="tai-sao-can-lien-ket-giao-thuc-ssh" tabindex="-1">Tại sao cần liên kết giao thức SSH? <a class="header-anchor" href="#tai-sao-can-lien-ket-giao-thuc-ssh" aria-label="Permalink to “Tại sao cần liên kết giao thức SSH?”">​</a></h3><p>GitHub hỗ trợ hai giao thức vận hành kho chính: giao thức HTTPS và giao thức SSH:</p><ul><li>Giao thức HTTPS: Mỗi thao tác (như push) đều cần nhập tài khoản và mật khẩu GitHub (hoặc Personal Access Token PAT). Quá trình xác minh phức tạp và có rủi ro rò rỉ mật khẩu.</li><li>Giao thức SSH: Xác thực được hoàn thành thông qua &quot;cặp khóa&quot;, do đó không cần nhập mật khẩu lặp lại, và truyền tải được mã hóa an toàn hơn.</li></ul><p>&quot;Liên kết giao thức SSH&quot; là bước tiên quyết để kích hoạt xác thực SSH GitHub — chỉ khi liên kết SSH public key cục bộ với tài khoản GitHub, GitHub mới có thể nhận diện thiết bị của bạn và cho phép vận hành SSH trên kho.</p><h3 id="logic-cot-loi-cua-lien-ket-vai-tro-cua-cap-khoa-ssh" tabindex="-1">Logic cốt lõi của &quot;liên kết&quot;: Vai trò của cặp khóa SSH <a class="header-anchor" href="#logic-cot-loi-cua-lien-ket-vai-tro-cua-cap-khoa-ssh" aria-label="Permalink to “Logic cốt lõi của &quot;liên kết&quot;: Vai trò của cặp khóa SSH”">​</a></h3><p>Xác thực SSH dựa vào cặp khóa (public key + private key), chúng là các file mã hóa khớp nhau. Sau khi tạo, bạn cần cung cấp &quot;public key&quot; cho GitHub (&quot;liên kết&quot;), và giữ &quot;private key&quot; trên thiết bị cục bộ:</p><ol><li>Private key: Được lưu trữ trong thư mục được chỉ định (thường là ~/.ssh/) trên thiết bị cục bộ (như máy tính), đóng vai trò là &quot;chìa khóa chuyên dụng của bạn&quot;, tuyệt đối không chia sẻ với bất kỳ ai.</li><li>Public key: Đây là một &quot;ổ khóa&quot; có thể chia sẻ công khai — bạn cần sao chép nó vào danh sách &quot;SSH keys&quot; của tài khoản GitHub (thao tác &quot;liên kết&quot;).</li></ol><p>Khi bạn vận hành kho GitHub thông qua SSH (ví dụ: git push <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:xxx/xxx.git):</p><ul><li>Thiết bị cục bộ của bạn sử dụng private key để mã hóa &quot;yêu cầu vận hành&quot; và gửi đến GitHub;</li><li>Sau khi nhận yêu cầu, GitHub cố gắng giải mã bằng public key bạn đã liên kết trước đó;</li><li>Nếu giải mã thành công, thiết bị của bạn được xác nhận là đã ủy quyền, thao tác được cho phép; nếu không, truy cập bị từ chối.</li></ul><h3 id="cac-buoc-cu-the-cua-lien-ket-quy-trinh-cot-loi" tabindex="-1">Các bước cụ thể của &quot;liên kết&quot; (Quy trình cốt lõi) <a class="header-anchor" href="#cac-buoc-cu-the-cua-lien-ket-quy-trinh-cot-loi" aria-label="Permalink to “Các bước cụ thể của &quot;liên kết&quot; (Quy trình cốt lõi)”">​</a></h3><p>Khi bạn đã hiểu nguyên lý, thao tác thực tế rất đơn giản — cốt lõi là &quot;tạo cặp khóa → tải public key lên GitHub&quot;:</p><ol><li><p>Tạo cặp khóa SSH cục bộ</p><ol><li>Sử dụng Trae để lấy public key (khuyến nghị) Prompt: <code>Help me create the SSH key needed for GitHub login. My email is your_email@gmail.com , Please return the public key for me to copy</code></li></ol><p><img src="'+y+'" alt=""></p><p>Sau khi nhập prompt, bạn cũng cần nhấn Enter trong terminal bên trái, nếu không lệnh sẽ tiếp tục chờ mà không thực thi. Vì Trae không thể giúp bạn thực hiện bất kỳ điều kiện phán đoán nào, chúng ta chỉ cần nhấn Enter liên tục.</p><p>Cuối cùng, bạn sẽ thấy Trae ở bên phải trả về public key mà nó đã đọc. Bạn chỉ cần sao chép nó và chuẩn bị dán trong bước tiếp theo.</p><p><img src="'+v+'" alt=""> 2. Lấy public key thủ công Mở terminal cục bộ của bạn (trên Windows sử dụng Git Bash hoặc PowerShell; trên macOS/Linux sử dụng Terminal), nhập lệnh sau (thay <a href="mailto:your_email@example.com" target="_blank" rel="noreferrer">your_email@example.com</a> bằng email bạn đã đăng ký tài khoản GitHub):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_email@example.com&quot;</span></span></code></pre></div><ol><li>Nhấn Enter để chấp nhận mặc định (đường dẫn file mặc định, không có passphrase, hoặc đặt passphrase theo cần). Điều này sẽ tạo hai file trong thư mục ~/.ssh/: <ul><li>id_ed25519: Private key (lưu cục bộ, <strong>tuyệt đối không chia sẻ</strong>);</li><li>id_ed25519.pub: Public key (cần tải lên GitHub).</li></ul></li></ol></li><li><p>&quot;Liên kết&quot; public key với tài khoản GitHub</p></li></ol><p>Đây là bước liên kết cốt lõi — thêm public key cục bộ vào danh sách &quot;SSH keys&quot; của tài khoản GitHub:</p><ol><li>Sao chép nội dung public key: <ol><li>Trae:</li><li>Windows: Mở C:\\Users&lt;your&gt;.ssh\\id_ed25519.pub bằng Notepad và sao chép toàn bộ nội dung;</li><li>macOS/Linux: Chạy cat ~/.ssh/id_ed25519.pub trong terminal và sao chép toàn bộ đầu ra (từ phần đầu SSH-ed25519 đến email ở cuối).</li></ol></li><li>Đăng nhập GitHub và vào trang &quot;SSH Key Management&quot;: <ol><li>Nhấp vào avatar góc trên bên phải → Settings → Menu bên trái SSH and GPG keys → Nhấp New SSH key. <img src="'+q+'" alt=""><img src="'+G+'" alt=""></li><li>Nhập bất kỳ tiêu đề nào (ví dụ: SSH của máy tính cục bộ của bạn), sau đó dán SSH public key bạn vừa lấy vào đây.</li></ol></li></ol><p><img src="'+H+'" alt=""></p><p><img src="'+S+'" alt=""></p><ol start="3"><li>Xác minh liên kết thành công</li></ol><p>Nhập lệnh sau trong terminal (<strong>Trae cũng có thể thực hiện các thao tác sau</strong>) để kiểm tra xem GitHub có thể nhận diện thiết bị của bạn hay không:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre></div><ul><li>Nếu bạn thấy nội dung tương tự như Hi [tên người dùng GitHub của bạn]! You&#39;ve successfully authenticated..., điều đó có nghĩa là bạn đã liên kết khóa thành công;</li><li>Nếu gặp lỗi, thường là do public key sao chép không đầy đủ, quyền private key quá cao (thư mục ~/.ssh/ cục bộ của bạn chỉ nên cho phép bạn đọc và ghi). Hãy kiểm tra các vấn đề này theo cần.</li></ul><h3 id="luu-y-quan-trong" tabindex="-1">Lưu ý quan trọng <a class="header-anchor" href="#luu-y-quan-trong" aria-label="Permalink to “Lưu ý quan trọng”">​</a></h3><p>Nếu bạn có nhiều thiết bị (như laptop và máy bàn), bạn cần tạo cặp khóa SSH riêng cho mỗi thiết bị và liên kết mỗi public key với cùng một tài khoản GitHub — mỗi thiết bị có &quot;thẻ kiểm soát truy cập&quot; riêng.</p><p>Tuyệt đối không chia sẻ private key của bạn (không tải lên GitHub hoặc chia sẻ với người khác), nếu không ai đó có thể mạo danh bạn vận hành kho của bạn. Nếu private key bị rò rỉ, hãy xóa ngay public key tương ứng khỏi GitHub và tạo cặp khóa mới.</p><p>Sau khi liên kết SSH, sử dụng địa chỉ kho định dạng SSH (ví dụ: <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:username/repository.git) để vận hành, thay vì định dạng HTTPS (ví dụ: <a href="https://github.com/username/repository.git" target="_blank" rel="noreferrer">https://github.com/username/repository.git</a>). Nếu bạn đã clone kho bằng HTTPS trước đó, có thể dùng git remote set-url origin <code>&lt;new&gt;</code> để chuyển đổi giao thức.</p><h1 id="su-dung-trae-đe-thao-tac-github" tabindex="-1">Sử dụng Trae để thao tác GitHub <a class="header-anchor" href="#su-dung-trae-đe-thao-tac-github" aria-label="Permalink to “Sử dụng Trae để thao tác GitHub”">​</a></h1><p>Chúng ta đã giải thích Git là gì, GitHub là gì, SSH là gì và cách cấu hình nó. Bây giờ bạn có thể tự do sử dụng Trae để thực hiện các thao tác Git. Đầu tiên, hãy học cách clone kho lưu trữ từ xa về máy cục bộ.</p><h2 id="git-clone-tai-xuong-kho-hien-co" tabindex="-1">Git clone: Tải xuống kho hiện có <a class="header-anchor" href="#git-clone-tai-xuong-kho-hien-co" aria-label="Permalink to “Git clone: Tải xuống kho hiện có”">​</a></h2><p>Bạn có thể trực tiếp cho nó biết địa chỉ kho bạn muốn clone</p><p><img src="'+f+'" alt=""></p><h2 id="git-pull-lay-cap-nhat-tu-kho-tu-xa" tabindex="-1">Git pull: Lấy cập nhật từ kho từ xa <a class="header-anchor" href="#git-pull-lay-cap-nhat-tu-kho-tu-xa" aria-label="Permalink to “Git pull: Lấy cập nhật từ kho từ xa”">​</a></h2><p>Trước khi cập nhật kho mỗi lần, vì nó có thể được bảo trì bởi nhiều người, bạn cần pull các thay đổi mới nhất trước. Sau đó, bạn có thể sửa đổi và push file.</p><p><strong>Nhớ bao gồm tên thư mục và đường dẫn tương đối hoặc tuyệt đối của nó, để tránh push sai kho.</strong></p><p>prompt:<code>Help me pull this repository AIID-TEST in ./AIID-TEST.</code></p><h2 id="git-commit-git-push-tam-luu-cap-nhat-va-push-len-github" tabindex="-1">Git commit &amp; Git push: Tạm lưu cập nhật và push lên GitHub <a class="header-anchor" href="#git-commit-git-push-tam-luu-cap-nhat-va-push-len-github" aria-label="Permalink to “Git commit &amp; Git push: Tạm lưu cập nhật và push lên GitHub”">​</a></h2><p>Khi mọi thứ đã sẵn sàng, bạn có thể thử sửa đổi file cục bộ, thêm hoặc xóa các mục trong thư mục. Sau đó, để Trae phát hiện các thay đổi và giúp bạn push lên GitHub.</p><p>prompt:<code>I finished. Commit and push to the repository AIID-TEST in ./AIID-TEST.</code></p><p><img src="'+x+'" alt=""></p><p>Push thành công. Bây giờ bạn có thể xem nội dung đã cập nhật trên GitHub.</p><h1 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h1><ul><li>Pro Git book <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/en/v2</a></li><li>GitHub Docs <a href="https://docs.github.com/en" target="_blank" rel="noreferrer">https://docs.github.com/en</a></li></ul>',92)])])}const L=t(F,[["render",_]]);export{w as __pageData,L as default};
